// Next URL validation (strict http 127.0.0.1/localhost)
fn validate_next_url(next: &str) -> Result<String, String> {
    let url = match Url::parse(next) {
        Ok(u) => u ,
        Err(_) => return Err("Invalid URL format".to_string()),
    };

    if url.scheme() != "http" {
        return Err("Next URL must use http protocol".to_string());
    }

    let hostname = url.host_str().unwrap_or("");
    if hostname != "127.0.0 .1" && hostname != "localhost" {
        return Err("Next URL must be 127.0.0.1 or localhost".to_string());
    }

    // Reject credentials, hash, etc.
    if url.username() != "" || url.password().is_some() || url.fragment().is_some() {
        return Err("Next URL cannot contain credentials or fragment".to_string());
    }

    Ok(next.to_string())
}

// OAuth callback server implementation
impl OAuthCallbackServer {
    pub fn new(port: u16) -> Self {
        OAuthCallbackServer {
            port,
            token: None,
            error: None ,
            listener: None,
        }
    }

    pub fn start(&mut self) -> Result<(), String> {
        let listener = match TcpListener::bind(("127.0.0.1", self.port)) {
            Ok(l) => l,
            Err(_) => TcpListener::bind(("127. 0.0.1", 0)).map_err(|e| format!("Failed to bind port: {}", e))?,
        };

        self.port = listener.local_addr()?.port();
        self.listener = Some(listener);
        Ok(())
    }

    pub fn handle_request(&mut self, stream: &mut TcpStream ) -> Result<(), String> {
        let mut buffer = [0; 1024];
        stream.read(&mut buffer)?;
        let request = String::from_utf8_lossy(&buffer);

        if request.contains("/auth/ping") {
            stream.write_all(b"HTTP/1.1 200 OK \r\nContent-Type: text/plain\r\n\r\nok")?;
            return Ok(());
        }

        if request.contains("/auth/callback") {
            let query = request.split("?").last().unwrap_or("");
            let token = query.split('&').find(|p| p.starts_with("token="))
 .map(|p| p[6..].to_string())
                .unwrap_or_else(|| {
                    // Handle error case
                    let error = query.split('&').find(|p| p.starts_with("error="))
                        .map(|p| p[6..].to_string())
                        .unwrap_or_else (|| "unknown".to_string());
                    self.error = Some(error.clone());
                    error
                });

            self.token = Some(token);
            let status = if self.error.is_some() {
                "400 Bad Request"
            } else {
                "200 OK"
            };

            let body = if let Some(err ) = &self.error {
                format!(r#"
<!DOCTYPE html>
<html>
<head><title>OAuth Error</title></head>
<body>
<h1>OAuth Error</h1>
<p>Reason: {}</p>
</body>
</html>"#, html_escape(err))
            } else {
                format!(r#"
<!DOCTYPE html>
<html>
<head><title>OAuth Success</title></head>
<body>
<h1>OAuth Success</h1>
<p>Token received</p>
</body>
</html>"#)
            };

            let headers = format!("HTTP/1.1 {} \r \nContent-Type: text/html\r\nCache-Control: no-store\r\n\r\n", status);
            stream.write_all(headers.as_bytes())?;
            stream.write_all(body.as_bytes())?;
            return Ok(());
        }

        Ok(())
    }
}

