      }
      @keyframes spin {
 0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
      }
      .message {
        font-size: 18px;
        color: #333;
      }
    </style>
  </head>
  <body>
    <div class=" container">
      <div class="spinner"></div>
      <div class="message">Returning to Tui...</div>
      <noscript>
        <p>Please click <a href="{{URL}}">here</a> to continue.</p>
      </noscript>
