const DEFAULT_OAUTH_CALLBACK_PORT = 3210;

export interface OAuthCallbackServer {
  readonly port: number;
  ready: Promise<void>;
  token: Promise<string>;
  close(): void;
}

/** Tolerant of both `&` and `?` separators: some hosted redirects append `?token` onto a callback that already carried `?state`. */
function queryParam(query: string, key: string): string | undefined {
  for (const pair of query.split(/[&?]/)) {
    const separator = pair.indexOf("=");
    const name = separator === -1 ? pair : pair.slice(0, separator);
    if (name === key) {
      const value = separator === -1 ? "" : pair.slice(separator + 1);
      return value.replace(/\+/g, " ");
    }
  }
  return undefined;
}

function percentDecode(value: string): string {
  const bytes = Buffer.from(value, "latin1");
  const out: number[] = [];
  let index = 0;
  const hex = (byte: number): number | undefined => {
    if (byte >= 48 && byte <= 57) return byte - 48;
    if (byte >= 97 && byte <= 102) return byte - 97 + 10;
    if (byte >= 65 && byte <= 70) return byte - 65 + 10;
    return undefined;
  };
  while (index < bytes.length) {
    const current = bytes[index]!;
    if (current === 37 && index + 2 < bytes.length) {
      const high = hex(bytes[index + 1]!);
      const low = hex(bytes[index + 2]!);
      if (high !== undefined && low !== undefined) {
        out.push(high * 16 + low);
        index += 3;
        continue;
      }
    }
    out.push(current);
    index += 1;
  }
  return Buffer.from(out).toString("utf8");
}

function callbackFailure(query: string): { message: string; cancelled: boolean } | undefined {
  const error = queryParam(query, "error");
  if (!error) return undefined;
  if (error === "access_denied") {
    return { message: "Sign-in was cancelled before it finished.", cancelled: true };
  }
  const description = queryParam(query, "error_description");
  const decoded = description ? percentDecode(description) : "";
  const message = decoded
    ? decoded
    : `The login page reported an error: ${percentDecode(error)}`;
  return { message: [...message].slice(0, 200).join(""), cancelled: false };
}

function listenOn(server: Server, port: number): Promise<number> {
  return new Promise((resolve, reject) => {
    const onError = (error: Error) => {
      server.off("listening", onListening);
      reject(error);
    };
    const onListening = () => {
      server.off("error", onError);
      const address = server.address();
      resolve(typeof address === "object" && address ? address.port : port);
    };
    server.once("error", onError);
    server.once("listening", onListening);
    server.listen(port, "127.0.0.1");
  });
}

/**
 * Localhost listener for the browser OAuth handoff. The handle is returned
 * immediately; `ready` resolves once the socket is bound (and `port` then
 * reflects any fallback).
 */
export function startOAuthCallbackServer(port: number): OAuthCallbackServer {
  let resolveReady!: () => void;
  let rejectReady!: (error: Error) => void;
  let resolveToken!: (token: string) => void;
  let rejectToken!: (error: Error) => void;
  const ready = new Promise<void>((resolve, reject) => {
    resolveReady = resolve;
    rejectReady = reject;
  });
  const token = new Promise<string>((resolve, reject) => {
    resolveToken = resolve;
    rejectToken = reject;
  });

  let settled = false;
  const succeed = (value: string) => {
    if (settled) return;
    settled = true;
    resolveToken(value);
  };
  const fail = (error: Error) => {
    if (settled) return;
    settled = true;
    rejectToken(error);
  };

  const handle: {
    port: number;
    ready: Promise<void>;
    token: Promise<string>;
    close(): void;
  } = {
    port,
    ready,
    token,
    close() {
      server.close();
      if (typeof server.closeAllConnections === "function") server.closeAllConnections();
