async function runOAuthCommand(provider: string): Promise<AuthSuccess> {
  if (provider !== "google" && provider !== "github") {
    throw new Error("usage: gamepigeon auth oauth <google|github>");
  }

  const callback = startOAuthCallbackServer(DEFAULT_OAUTH_CALLBACK_PORT);
  try {
    await callback.ready;
    const next = `http://127.0.0.1:${callback.port}/auth/callback`;
    const oauthUrl = `${requireAuthBaseUrl()}/cli/oauth?provider=${provider}&next=${encodeURIComponent(next)}`;
    const opened = openBrowser(oauthUrl);
    if (opened) {
      console.log(`Waiting for you to finish signing in with ${provider}...`);
    } else {
      console.log("Open this URL in your browser to finish signing in:");
      console.log(oauthUrl);
    }
    const sessionToken = await callback.token;
    const user = await resolveUser(sessionToken);
    saveSession(sessionToken, user);
    console.log(`Signed in as ${user.email}`);
    return { kind: "signed_in", method: provider, userId: user.id };
  } finally {
    callback.close();
  }
}

