import { getMigrations } from "better-auth/db/migration";
import {
  createAuth,
  oauthCredentials,
  trustedOrigins,
  type AuthEnv,
  type OAuthProviderName,
} from "./auth";
import { handoffRedirectPage, handoffUnauthorizedPage } from "./handoff-page";

const SESSION_COOKIE = "better-auth.session_token";
const SECURE_SESSION_COOKIE = `__Secure-${SESSION_COOKIE}`;

/** A CLI callback URL: plain `http:` to 127.0.0.1 or localhost, no userinfo. */
export function trustedCliNext(value: string | null): URL | null {
  if (value == null || value === "" || value !== value.trim()) return null;
  try {
    const url = new URL(value);
    if (url.protocol !== "http:") return null;
    if (url.hostname !== "127.0.0.1" && url.hostname !== "localhost") return null;
    if (url.username !== "" || url.password !== "") return null;
    return url;
  } catch {
    return null;
  }
}

function jsonError(status: number, error: string, extra: HeadersInit = {}): Response {
  return Response.json({ error }, { status, headers: extra });
}

function cookieValue(header: string | null, name: string): string | undefined {
  if (!header) return undefined;
  for (const part of header.split(";")) {
    const trimmed = part.trim();
    const separator = trimmed.indexOf("=");
    if (separator === -1) continue;
    if (trimmed.slice(0, separator) === name) return trimmed.slice(separator + 1);
  }
  return undefined;
}

function sessionTokenFromCookie(header: string | null): string | undefined {
  return cookieValue(header, SESSION_COOKIE) || cookieValue(header, SECURE_SESSION_COOKIE);
}

async function handleCliOAuth(request: Request, env: AuthEnv, url: URL): Promise<Response> {
  const provider = url.searchParams.get("provider");
  if (provider !== "google" && provider !== "github") {
    return jsonError(400, "Unsupported provider. Use google or github.");
  }

  if (!oauthCredentials(env, provider as OAuthProviderName)) {
    return jsonError(503, `${provider} sign-in is not configured.`);
  }

  const next = trustedCliNext(url.searchParams.get("next"));
  if (!next) {
    return jsonError(400, "Invalid next URL. Use a plain http://127.0.0.1 or http://localhost callback.");
  }

  const handoff = new URL("/cli/handoff", env.BETTER_AUTH_URL);
  handoff.searchParams.set("next", next.toString());

  const auth = createAuth(env);
  const origin = new URL(env.BETTER_AUTH_URL).origin;
  const headers = new Headers({
    "content-type": "application/json",
    origin,
    cookie: request.headers.get("cookie") ?? "",
  });
  const signIn = await auth.handler(new Request(new URL("/api/auth/sign-in/social", env.BETTER_AUTH_URL), {
    method: "POST",
    headers,
    body: JSON.stringify({
      provider,
      callbackURL: handoff.toString(),
      disableRedirect: true,
    }),
  }));

  let payload: { url?: string } | null = null;
  try {
    payload = await signIn.json() as { url?: string };
  } catch {
    payload = null;
  }
  if (!payload?.url) {
    return jsonError(500, "Could not start sign-in.");
  }

  const redirect = new Headers();
  redirect.set("location", payload.url);
  redirect.set("cache-control", "no-store");
  const cookies = typeof signIn.headers.getSetCookie === "function"
    ? signIn.headers.getSetCookie()
    : [];
  if (cookies.length > 0) {
    for (const cookie of cookies) redirect.append("set-cookie", cookie);
  } else {
    const single = signIn.headers.get("set-cookie");
    if (single) redirect.set("set-cookie", single);
  }
  return new Response(null, { status: 302, headers: redirect });
}

async function handleCliHandoff(request: Request, env: AuthEnv, url: URL): Promise<Response> {
  const next = trustedCliNext(url.searchParams.get("next"));
  if (!next) {
    return jsonError(400, "Invalid next URL. Use a plain http://127.0.0.1 or http://localhost callback.");
  }

  const auth = createAuth(env);
  let session: { user?: unknown } | null = null;
  try {
    session = await auth.api.getSession({ headers: request.headers });
  } catch {
    session = null;
  }
  const token = sessionTokenFromCookie(request.headers.get("cookie"));
  if (!session?.user || !token) {
    return new Response(handoffUnauthorizedPage(), {
      status: 401,
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "no-store",
        "referrer-policy": "no-referrer",
      },
    });
  }

  next.searchParams.append("token", token);
  const redirectTo = next.toString();
  return new Response(handoffRedirectPage(redirectTo), {
    status: 200,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "referrer-policy": "no-referrer",
    },
  });
}

