test("oauth callback server answers ping, captures a token, and ignores state", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");

    const response = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=ignored&token=session-secret`,
    );
    expect(response.status).toBe(200);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toContain("signed in");
    await expect(callback.token).resolves.toBe("session-secret");
  } finally {
    callback.close();
  }
});

test("oauth callback server reads a token glued onto state with a second ?", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const raw = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce?token=glued-token`,
    );
    if (!raw.ok || !(await callback.token.catch(() => ""))) {
      // fetch() may encode the second `?`; drive the listener with a raw path instead.
      const retry = startOAuthCallbackServer(0);
      try {
        await retry.ready;
        await new Promise<void>((resolve, reject) => {
          const request = new Request("http://127.0.0.1/auth/callback?state=nonce?token=glued-token");
          // Use the HTTP parser against the already-bound port via a raw socket path.
          const { request: httpRequest } = require("node:http") as typeof import("node:http");
          const req = httpRequest(
            {
              hostname: "127.0.0.1",
              port: retry.port,
              path: "/auth/callback?state=nonce?token=glued-token",
            },
            (response) => {
              response.resume();
              response.on("end", resolve);
            },
          );
          req.on("error", reject);
          req.end();
          void request;
        });
        await expect(retry.token).resolves.toBe("glued-token");
      } finally {
        retry.close();
      }
      return;
    }
    await expect(callback.token).resolves.toBe("glued-token");
  } finally {
    callback.close();
  }
});

test("oauth callback server reports cancellation and escapes other errors", async () => {
  const cancelled = startOAuthCallbackServer(0);
  try {
    await cancelled.ready;
    const response = await fetch(
      `http://127.0.0.1:${cancelled.port}/auth/callback?error=access_denied`,
    );
    expect(response.status).toBe(400);
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(await response.text()).toMatch(/cancelled/i);
    await expect(cancelled.token).rejects.toThrow(/cancelled/i);
  } finally {
    cancelled.close();
  }

  const failed = startOAuthCallbackServer(0);
  try {
    await failed.ready;
    const description = "<script>alert(1)</script>";
    const response = await fetch(
      `http://127.0.0.1:${failed.port}/auth/callback?error=server_error&error_description=${encodeURIComponent(description)}`,
    );
    expect(response.status).toBe(400);
    expect(response.headers.get("cache-control")).toBe("no-store");
    const body = await response.text();
    expect(body).not.toContain("<script>");
    expect(body).toContain("<script>");
    await expect(failed.token).rejects.toThrow(description);
  } finally {
    failed.close();
  }
});

test("oauth callback server falls back to a free port when the requested one is busy", async () => {
  const blocker = createServer();
  await new Promise<void>((resolve, reject) => {
    blocker.once("error", reject);
    blocker.listen(0, "127.0.0.1", () => resolve());
  });
  const address = blocker.address();
  const busyPort = typeof address === "object" && address ? address.port : 0;
  const callback = startOAuthCallbackServer(busyPort);
  try {
    await callback.ready;
    expect(callback.port).not.toBe(busyPort);
    expect(callback.port).toBeGreaterThan(0);
    const ping = await fetch(`http://127.0.0.1:${callback.port}/auth/ping`);
    expect(ping.status).toBe(200);
    expect(await ping.text()).toBe("ok");
  } finally {
    callback.close();
    await new Promise<void>((resolve) => blocker.close(() => resolve()));
  }
});

