import { env } from "cloudflare:workers";
import { expect, test } from "vitest";
import worker from "../src/index";

async function workerFetch(path: string, init?: RequestInit): Promise<Response> {
  return worker.fetch(new Request(`https://auth.runretroarcade.com${path}`, init), env);
}

test("GET /cli/oauth rejects providers other than google and github", async () => {
  const response = await workerFetch(
    "/cli/oauth?provider=facebook&next=http://127.0.0.1:3210/auth/callback",
  );
  expect(response.status).toBe(400);
});

test("GET /cli/oauth is unavailable when the provider has no credentials", async () => {
  const response = await workerFetch(
    "/cli/oauth?provider=google&next=http://127.0.0.1:3210/auth/callback",
  );
  expect(response.status).toBe(503);
});

test("GET /cli/handoff rejects a next target that is not localhost http before touching the session", async () => {
  const response = await workerFetch("/cli/handoff?next=https://evil.example/steal");
  expect(response.status).toBe(400);
});

test("GET /cli/handoff rejects next URLs with credentials or a non-loopback host", async () => {
  const rejected = [
    "http://example.com/",
    "https://127.0.0.1:3210/auth/callback",
    "http://127.0.0.1.evil.com/auth/callback",
    "http://user@127.0.0.1:3210/auth/callback",
    "http://[::1]:3210/auth/callback",
  ];
  for (const next of rejected) {
    const response = await workerFetch(`/cli/handoff?next=${encodeURIComponent(next)}`);
    expect(response.status, next).toBe(400);
  }
});

test("GET /cli/handoff answers 401 with oauth guidance when there is no session", async () => {
  const response = await workerFetch("/cli/handoff?next=http://127.0.0.1:3210/auth/callback");
  expect(response.status).toBe(401);
  expect(await response.text()).toMatch(/oauth/i);
});

test("GET /cli/oauth validates next the same way once credentials would otherwise start sign-in", async () => {
  const response = await workerFetch("/cli/oauth?provider=github&next=https://evil.example/");
  // No GitHub credentials in the test env, so this stays 503 rather than starting OAuth.
  expect(response.status).toBe(503);
});

