test("oauth callback server reads a token glued onto state with a second ?", async () => {
  const callback = startOAuthCallbackServer(0);
  try {
    await callback.ready;
    const raw = await fetch(
      `http://127.0.0.1:${callback.port}/auth/callback?state=nonce?token=glued-token`,
    );
    if (!raw.ok || !(await callback.token.catch(() => ""))) {
      // fetch() may encode the second `?`; drive the listener with a raw path instead.
      const retry = startOAuthCallbackServer(0);
      try {
        await retry.ready;
        await new Promise<void>((resolve, reject) => {
          const request = new Request("http://127.0.0.1/auth/callback?state=nonce?token=glued-token");
          // Use the HTTP parser against the already-bound port via a raw socket path.
          const { request: httpRequest } = require("node:http") as typeof import("node:http");
          const req = httpRequest(
            {
              hostname: "127.0.0.1",
              port: retry.port,
              path: "/auth/callback?state=nonce?token=glued-token",
            },
            (response) => {
              response.resume();
              response.on("end", resolve);
            },
          );
          req.on("error", reject);
          req.end();
          void request;
        });
        await expect(retry.token).resolves.toBe("glued-token");
      } finally {
        retry.close();
      }
      return;
    }
    await expect(callback.token).resolves.toBe("glued-token");
  } finally {
    callback.close();
  }
});

