/** Append `token=<cookie>` without re-encoding the cookie value, preserving existing query. */
function appendTokenQuery(next: URL, token: string): string {
  const href = next.toString();
  const hashIndex = href.indexOf("#");
  const before = hashIndex === -1 ? href : href.slice(0, hashIndex);
  const hash = hashIndex === -1 ? "" : href.slice(hashIndex);
